def _post_trust_credentials_verify_receipt(self, tenant: str) -> None:
    # POST /v1/trust/credentials/verify-receipt：跨系统凭证验真
    # 签名回执（纯只读）。
    # 1) 请求体须恰含 body、signature、verifier_did、nonce：
    #    非法 JSON/非对象、键集不符、verifier_did 非非空串、
    #    nonce 非 1..256 码点非空串均 400 且仅 {error}；
    # 2) body、signature 按既有外部凭证验真全规则处理，任一失败
    #    先 200 恰返 {valid:false,reason}（沿用原原因），不查询
    #    验证者；
    # 3) 仅成功才查本租户验证者 DID：未知或跨租户 404、停用 409，
    #    均仅 {error}；
    # 4) 成功 200 按键序恰为 valid、receipt、receipt_signature；
    #    receipt 恰含 credential_id、issuer_did、issuer_key_version、
    #    credential_digest、verifier_did、verifier_key_version、
    #    nonce，摘要为 {body,signature} 递归键升序紧凑 UTF-8 JSON
    #    的 SHA-256 小写 64 位 hex；receipt_signature 以验证者当前
    #    私钥对 receipt 规范化 JSON 按 ES256 裸 R||S 无填充
    #    base64url 规则签名。不落盘、不审计。
    data = self._read_json()
    expected_fields = (
        "body",
        "signature",
        "verifier_did",
        "nonce",
    )
    if set(data) != set(expected_fields):
        missing = [f for f in expected_fields if f not in data]
        if missing:
            raise ValidationError(
                f"缺少字段: {', '.join(missing)}"
            )
        extra = sorted(set(data) - set(expected_fields))
        raise ValidationError(
            f"多余字段: {', '.join(extra)}"
        )
    verifier_did = data["verifier_did"]
    if not isinstance(verifier_did, str) or not verifier_did:
        raise ValidationError(
            "字段 verifier_did 必须为非空字符串"
        )
    nonce = data["nonce"]
    if not isinstance(nonce, str) or not nonce:
        raise ValidationError("字段 nonce 必须为非空字符串")
    if not 1 <= len(nonce) <= 256:
        raise ValidationError(
            "字段 nonce 长度须为 1 到 256 个 Unicode 码点"
        )

    # 先按既有外部凭证验真全规则处理 body、signature；失败沿用
    # 原原因返回 200/valid:false，且不查询验证者 DID。
    verify_data = {"body": data["body"], "signature": data["signature"]}
    try:
        valid, reason = store.verify_trust_credential(
            tenant, verify_data
        )
    except Exception:  # noqa: BLE001 验签失败绝不暴露内部细节
        self._send_invalid("验签过程发生内部错误")
        return
    if not valid:
        self._send_json(
            200,
            {"valid": False, "reason": reason or "验签失败"},
        )
        return

    body = verify_data["body"]
    issuer_key_version = body.get("issuer_key_version", 1)

    # 仅验真成功才查本租户验证者 DID：未知（含跨租户）404、
    # 停用 409，均仅 {error}。
    verifier_key_version, verifier_private_pem = (
        store.get_verify_receipt_signer(tenant, verifier_did)
    )

    # 摘要覆盖 {body,signature} 的递归键升序紧凑 UTF-8 JSON。
    digest_input = {"body": body, "signature": data["signature"]}
    credential_digest = hashlib.sha256(
        crypto.canonicalize(digest_input)
    ).hexdigest()
    receipt = {
        "credential_id": body["credential_id"],
        "issuer_did": body["issuer_did"],
        "issuer_key_version": issuer_key_version,
        "credential_digest": credential_digest,
        "verifier_did": verifier_did,
        "verifier_key_version": verifier_key_version,
        "nonce": nonce,
    }
    receipt_signature = crypto.sign(receipt, verifier_private_pem)
    self._send_json(
        200,
        {
            "valid": True,
            "receipt": receipt,
            "receipt_signature": receipt_signature,
        },
    )

def _post_trust_credentials_import(self, tenant: str) -> None:
    # 外部凭证导入：请求体恰为 {body, signature}，body 规则同
    # /v1/trust/credentials/verify（必含 credential_id/issuer_did/
    # subject_did/claims/issued_at）。请求/字段非法由 _read_json

"""ES256 签名与规范化 JSON。

ES256 即 ECDSA over P-256 与 SHA-256。签名以 JWS 约定编码：
64 字节裸 R||S 的 base64url（无填充）。cryptography 库签出的是 DER，
这里在 DER 与 R||S 之间做转换。
"""

import base64
import json
import re
from typing import Any, Dict

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import ec
from cryptography.hazmat.primitives.asymmetric.utils import (
    decode_dss_signature,
    encode_dss_signature,
)

__all__ = [
    "InvalidSignature",
    "MalformedSignature",
    "canonicalize",
    "generate_private_key_pem",
    "public_key_pem_from_private",
    "validate_public_key_pem",
    "validate_signature_format",
    "validate_signature_format_strict",
    "sign",
    "verify",
]


class MalformedSignature(ValueError):
    """签名编码格式非法（无法解码或不是 64 字节裸 R||S）。"""


def _b64url(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")


def _b64url_decode(text: str) -> bytes:
    padding = "=" * (-len(text) % 4)
    return base64.urlsafe_b64decode(text + padding)


def canonicalize(body: Dict[str, Any]) -> bytes:
    """正文按 key 升序的规范化 JSON 序列化（紧凑、UTF-8 字节）。"""
    return json.dumps(
        body, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")


def generate_private_key_pem() -> str:
    """生成 P-256 私钥，返回 PKCS8 PEM 字符串。"""
    private_key = ec.generate_private_key(ec.SECP256R1())
    pem = private_key.private_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PrivateFormat.PKCS8,
        encryption_algorithm=serialization.NoEncryption(),
    )
    return pem.decode("utf-8")


def public_key_pem_from_private(private_pem: str) -> str:
    """从私钥 PEM 导出对应的 SubjectPublicKeyInfo 公钥 PEM。"""
    private_key = serialization.load_pem_private_key(
        private_pem.encode("utf-8"), password=None
    )
    if not isinstance(private_key, ec.EllipticCurvePrivateKey):
        raise ValueError("私钥不是 P-256 椭圆曲线私钥")
    if not isinstance(private_key.curve, ec.SECP256R1):
        raise ValueError("私钥曲线不是 P-256")
    pem = private_key.public_key().public_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PublicFormat.SubjectPublicKeyInfo,
    )
    return pem.decode("utf-8")


def _load_public_key(public_pem: str) -> ec.EllipticCurvePublicKey:
    try:
        key = serialization.load_pem_public_key(public_pem.encode("utf-8"))
    except (ValueError, TypeError) as exc:
        raise ValueError(f"公钥 PEM 无法解析: {exc}") from exc
    if not isinstance(key, ec.EllipticCurvePublicKey) or not isinstance(
        key.curve, ec.SECP256R1
    ):
        raise ValueError("公钥不是 P-256 椭圆曲线公钥")
    return key


def validate_public_key_pem(public_pem: str) -> None:
    """校验公钥 PEM 可解析且为 ES256 所需的 P-256 公钥，否则抛 ValueError。"""
    _load_public_key(public_pem)


def _load_private_key(private_pem: str) -> ec.EllipticCurvePrivateKey:
    try:
        key = serialization.load_pem_private_key(
            private_pem.encode("utf-8"), password=None
        )
    except (ValueError, TypeError) as exc:
        raise ValueError(f"私钥 PEM 无法解析: {exc}") from exc
    if not isinstance(key, ec.EllipticCurvePrivateKey) or not isinstance(
        key.curve, ec.SECP256R1
    ):
        raise ValueError("私钥不是 P-256 椭圆曲线私钥")
    return key


def sign(body: Dict[str, Any], private_pem: str) -> str:
    """对规范化正文做 ES256 签名，返回 base64url(R||S)。"""
    private_key = _load_private_key(private_pem)
    der = private_key.sign(
        canonicalize(body), ec.ECDSA(hashes.SHA256())
    )
    r, s = decode_dss_signature(der)
    raw = r.to_bytes(32, "big") + s.to_bytes(32, "big")
    return _b64url(raw)


def validate_signature_format(signature_b64: str) -> None:
    """校验签名编码格式：须为可解码的 base64url 且裸 R||S 恰为 64 字节。

    仅检查格式，不做密码学验签。格式非法抛 MalformedSignature。
    """
    try:
        raw = _b64url_decode(signature_b64)
    except Exception as exc:  # noqa: BLE001 解码异常（含 binascii）均属格式问题
        raise MalformedSignature("签名不是合法的 base64url 编码") from exc
    if len(raw) != 64:
        raise MalformedSignature("签名长度不是 64 字节，非合法 ES256 签名")


# 严格格式：64 字节裸 R||S 的无填充 base64url 恰为 86 个字符
_RAW_RS_B64URL_STRICT_RE = re.compile(r"[A-Za-z0-9_-]{86}")


def validate_signature_format_strict(signature_b64: str) -> None:
    """严格校验签名编码格式：恰为 86 个 base64url 字符（无填充、无字
    母表外字符），解码恰为 64 字节裸 R||S，且无填充 base64url 重编码
    与原文逐字符一致（排除填充与非规范尾位）。

    仅检查格式，不做密码学验签。格式非法抛 MalformedSignature。
    """
    if not isinstance(signature_b64, str) or not (
        _RAW_RS_B64URL_STRICT_RE.fullmatch(signature_b64)
    ):
        raise MalformedSignature(
            "签名不是 86 字符的无填充 base64url 编码"
        )
    raw = _b64url_decode(signature_b64)
    if len(raw) != 64 or _b64url(raw) != signature_b64:
        raise MalformedSignature(
            "签名不是规范的 64 字节裸 R||S 无填充 base64url 编码"
        )


def verify(body: Dict[str, Any], signature_b64: str, public_pem: str) -> None:
    """校验签名：格式非法抛 MalformedSignature，验签失败抛 InvalidSignature。"""
    validate_signature_format(signature_b64)
    public_key = _load_public_key(public_pem)
    raw = _b64url_decode(signature_b64)
    r = int.from_bytes(raw[:32], "big")
    s = int.from_bytes(raw[32:], "big")
    der = encode_dss_signature(r, s)
    public_key.verify(der, canonicalize(body), ec.ECDSA(hashes.SHA256()))

def verify_trust_credential(
    self,
    tenant_id: str,
    data: Any,
) -> Tuple[bool, str]:
    """验证未在本租户签发或存储的外部凭证，返回 (是否有效, 失败原因)。

    校验顺序：请求结构 -> 凭证字段 -> 锚点 -> 签名格式 -> 密码学验签。
    - 请求体须恰含 body（对象）与 signature（非空字符串），其余字段
      （含缺失、多余字段、非对象）均按请求错误；
    - body 须含 credential_id/issuer_did/subject_did/claims/issued_at，
      依次为非空字符串、非空字符串、非空字符串、对象、非空字符串；
      issuer_key_version 可省略（按版本 1 查锚点且不得注入签名正文），
      提供时须为非布尔正整数；其他扩展字段允许且全部参与签名；
    - 锚点按本租户 (issuer_did, 版本) 查找，仅 active 的 P-256 公钥
      可用，缺失或 revoked 失败；
    - 签名为 ES256/SHA-256，64 字节裸 R||S 的无填充 base64url，覆盖
      完整 body（递归排序紧凑 JSON）；
    - 原验真成功后按当前租户查 issuer_did 外部停用通告，命中返回
      “外部签发DID已停用：<reason>”，仅他租户有通告不影响结论。
    只读：不登记 DID/凭证，不写凭证、状态或审计，绝不向上抛异常。
    """
    # 1. 请求结构
    if not isinstance(data, dict):
        return False, "请求不合法: 请求体必须为 JSON 对象"
    if set(data) != {"body", "signature"}:
        missing = [f for f in ("body", "signature") if f not in data]
        if missing:
            return False, f"请求缺少字段: {', '.join(missing)}"
        extra = sorted(set(data) - {"body", "signature"})
        return False, f"请求含多余字段: {', '.join(extra)}"
    body = data["body"]
    signature = data["signature"]
    if not isinstance(body, dict):
        return False, "请求不合法: 字段 body 必须为 JSON 对象"
    if not isinstance(signature, str) or not signature:
        return False, "请求不合法: 字段 signature 必须为非空字符串"

    # 2. 凭证字段
    required_str = (
        "credential_id",
        "issuer_did",
        "subject_did",
        "issued_at",
    )
    for field in required_str:
        if field not in body:
            return False, f"凭证缺少字段: {field}"
        value = body[field]
        if not isinstance(value, str) or not value:
            return False, f"凭证字段 {field} 必须为非空字符串"
    if "claims" not in body:
        return False, "凭证缺少字段: claims"
    if not isinstance(body["claims"], dict):
        return False, "凭证字段 claims 必须为 JSON 对象"
    key_version = 1
    if "issuer_key_version" in body:
        version_obj = body["issuer_key_version"]
        if (
            not isinstance(version_obj, int)
            or isinstance(version_obj, bool)
            or version_obj < 1
        ):
            return False, "凭证字段 issuer_key_version 必须为正整数"
        key_version = version_obj
    issuer_did = body["issuer_did"]

    # 3. 锚点：本租户 (issuer_did, 版本)，仅 active 的 P-256 公钥
    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        anchors = (
            bucket["trust_anchors"].get(issuer_did)
            if bucket is not None else None
        )
        row = (
            anchors.get(str(key_version))
            if anchors is not None else None
        )
        public_pem = row.get("public_key", "") if row is not None else ""
        status = row.get("status", "active") if row is not None else None
        uses = row.get("uses") if row is not None else None
    if row is None:
        return False, (
            f"锚点不存在: {issuer_did}#{key_version}"
        )
    if status == "revoked":
        return False, f"锚点已吊销: {issuer_did}#{key_version}"
    # 用途白名单：active 锚点无 vc 用途时按锚点不可用处理
    if uses is not None and "vc" not in uses:
        return False, (
            f"锚点不存在: {issuer_did}#{key_version}"
        )
    try:
        crypto.validate_public_key_pem(public_pem)
    except (ValueError, TypeError):
        return False, (
            f"锚点公钥不可用: {issuer_did}#{key_version} 不是合法 P-256 公钥"
        )

    # 4/5. 签名格式与密码学验签：签名覆盖完整 body 的规范化 JSON。
    # 省略 issuer_key_version 时不得向签名正文注入该字段。
    try:
        crypto.verify(body, signature, public_pem)
    except crypto.MalformedSignature:
        return False, "签名格式错误: 不是合法的 ES256 签名编码"
    except crypto.InvalidSignature:
        return False, "签名校验失败，凭证正文或签名可能被改动"
    except Exception:  # noqa: BLE001 验签绝不向上抛错或泄露内部细节
        return False, "签名校验失败: 验签过程发生内部错误"

    # 6. 有效期：仅在请求 body 提供 expires_at 时检查（缺失保持兼容，
    # 无期限）。须为 UTC 秒精度 Z 格式；当前时间 >= expires_at 判
    # 到期。只读，不写任何状态、不记审计。
    if "expires_at" in body:
        expires_value = body["expires_at"]
        if (
            not isinstance(expires_value, str)
            or not _UTC_Z_SHAPE_RE.match(expires_value)
        ):
            return False, (
                "凭证字段 expires_at 必须为 UTC 秒精度 Z 格式"
                "（YYYY-MM-DDTHH:MM:SSZ）"
            )
        try:
            expires_dt = _parse_utc_z(expires_value)
        except ValueError:
            return False, (
                "凭证字段 expires_at 必须为 UTC 秒精度 Z 格式"
                "（YYYY-MM-DDTHH:MM:SSZ）"
            )
        if datetime.now(timezone.utc) >= expires_dt:
            return False, CREDENTIAL_EXPIRED_REASON

    # 7. 原验真成功后、合并凭证状态前查本租户 issuer_did 外部停用
    #    通告：命中返回“外部签发DID已停用：<reason>”；无通告或仅他
    #    租户有通告维持原结论。只读，不写状态、不记审计。
    deactivation_reason = self._external_did_deactivation_reason(
        tenant_id, issuer_did, EXTERNAL_ISSUER_DID_DEACTIVATED_REASON_PREFIX
    )
    if deactivation_reason is not None:
        return False, deactivation_reason
    return True, ""

